cd /app && python - <<'EOF'
import ast, glob, os, re
orig = ast.parse(open('/tmp/opencode/orig/reports_orig.py').read())
pub=[]
for n in orig.body:
    names=[]
    if isinstance(n,(ast.FunctionDef,ast.ClassDef)): names=[n.name]
    elif isinstance(n,ast.Assign):
        for t in n.targets:
            if isinstance(t,ast.Name): names.append(t.id)
    elif isinstance(n,ast.AnnAssign) and isinstance(n.target,ast.Name): names=[n.target.id]
    pub += [x for x in names if not x.startswith('_')]
print(len(pub), len(set(pub)))
home={}
for f in glob.glob('tally/reports/**/*.py', recursive=True):
    mod = f[:-3].replace('/','.')
    mod = re.sub(r'\.__init__$','',mod)
    if f.endswith('__init__.py'): continue
    for n in ast.parse(open(f).read()).body:
        names=[]
        if isinstance(n,(ast.FunctionDef,ast.ClassDef)): names=[n.name]
        elif isinstance(n,ast.Assign):
            names=[t.id for t in n.targets if isinstance(t,ast.Name)]
        elif isinstance(n,ast.AnnAssign): names=[n.target.id]
        for x in names:
            if x in pub: home.setdefault(x,[]).append(mod)
missing=[p for p in pub if p not in home]; print('missing',missing)
print({k:v for k,v in home.items() if len(v)>1})
by={}
for p in pub: by.setdefault(home[p][0].replace('tally.reports','',1),[]).append(p)
alls = re.search(r'__all__ = \[.*?\n\]\n', open('/tmp/opencode/orig/reports_orig.py').read(), re.S).group(0)
doc = ast.get_docstring(orig)
out = '"""'+doc+'\n"""\n\n'
out += 'from __future__ import annotations\n\n'
# order: layers
for mod in sorted(by, key=lambda m:(m.count('.'),m)):
    out += f"from .{mod.lstrip('.')} import (\n" + ''.join(f"    {x},\n" for x in sorted(by[mod])) + ")\n"
out += '\n' + alls
open('tally/reports/__init__.py','w').write(out)
EOF
