import ast, glob, builtins
for f in sorted(glob.glob('tally/reports/**/*.py', recursive=True)):
    tree = ast.parse(open(f).read())
    bound=set(dir(builtins))
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.ClassDef)): bound.add(n.name)
        if isinstance(n,ast.arg): bound.add(n.arg)
        if isinstance(n,ast.Name) and isinstance(n.ctx,(ast.Store,ast.Del)): bound.add(n.id)
        if isinstance(n,(ast.Import,ast.ImportFrom)):
            for a in n.names: bound.add((a.asname or a.name).split('.')[0])
        if isinstance(n,ast.ExceptHandler) and n.name: bound.add(n.name)
    used=set()
    for n in ast.walk(tree):
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load) and n.id not in bound: print(f,'UNDEF',n.id,n.lineno)
    # unused imports
    imp={}
    for n in ast.walk(tree):
        if isinstance(n,(ast.Import,ast.ImportFrom)) and not f.endswith('__init__.py'):
            for a in n.names: imp[(a.asname or a.name).split('.')[0]]=n.lineno
    loads={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)}|{n.value.id for n in ast.walk(tree) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name)}
    srcs=open(f).read()
    for k,l in imp.items():
        if k not in loads and k!='annotations' and srcs.count(k)<2: print(f,'UNUSED',k)
