import ast, glob, os
root='tally/reports'
layer_of={'errors':0,'tables':0,'state':0,'system':0,'formatting':1,'model':1,'loading':2,'aggregate':3,'renderers':4,'cli':5,'__init__':6}
mods={}
for f in glob.glob(root+'/**/*.py',recursive=True):
    n=sum(1 for _ in open(f)); 
    if n>400: print('BIG',f,n)
    rel=os.path.relpath(f,root)[:-3].split(os.sep)
    if rel[-1]=='__init__': rel=rel[:-1] or ['__init__']
    mods[tuple(rel)]=f
def lay(m): return layer_of[m[0]]
edges=set()
for m,f in mods.items():
    pkg = list(m) if f.endswith('__init__.py') else list(m[:-1])
    for n in ast.walk(ast.parse(open(f).read())):
        targets=[]
        if isinstance(n,ast.Import):
            for a in n.names:
                assert not a.name.startswith('tally'),(f,a.name)
        if isinstance(n,ast.ImportFrom):
            if n.level==0:
                assert not (n.module or '').startswith('tally'),(f,n.module); continue
            base=pkg[:len(pkg)-(n.level-1)] if n.level>1 else pkg
            mod=base+(n.module.split('.') if n.module else [])
            for a in n.names:
                cand=tuple(mod+[a.name])
                if cand in mods: targets.append(cand)
                else:
                    t=tuple(mod); 
                    targets.append(t if t else ('__init__',))
        for t in targets: edges.add((m,t))
bad=[(a,b) for a,b in edges if lay(b)>lay(a) and a!=('__init__',)]
print('layer violations',bad)
# cycles
import collections
g=collections.defaultdict(set)
for a,b in edges: g[a].add(b)
state={}
def dfs(u,stack):
    state[u]=1
    for v in g[u]:
        if state.get(v)==1: print('CYCLE',stack+[u,v])
        elif v not in state: dfs(v,stack+[u])
    state[u]=2
for m in mods:
    if m not in state: dfs(m,[])
# same-layer package-level: sub-pkg init imports
# global vars
for m,f in mods.items():
    t=ast.parse(open(f).read())
    for fn in ast.walk(t):
        if isinstance(fn,ast.Global): print('global',f,fn.names)
init=ast.parse(open(root+'/__init__.py').read())
print({type(x).__name__ for x in init.body})
print(open('tally/reports/__init__.py').read().count('__all__'))
